-- Reorganización de carta: nuevo paso de salsas (Salsa de yogurt
-- Blanca / Salsa de tomate Roja / Salsa picante, blanca y roja marcadas
-- por defecto) para los 24 productos de Kebab/Dürüm/Lahmacum. Si el
-- cliente quita todas las salsas, en cocina sale "Sin salsa" en vez de
-- "sin blanca, sin roja, sin picante" por separado (textoSiVacio).
--
-- Además, para "solo carne" y "loco" (6 productos) se ELIMINA el paso de
-- quitar ingredientes (no llevan ensalada), pero sí mantienen salsas y
-- extras.
--
-- Para el resto (ternera/pollo/mixto/falafel/vegetal con queso/doble, 18
-- productos), el paso de quitar gana "ingrediente" por opción y
-- resumenQuitarMuchos: a partir de 3 ingredientes quitados, en cocina sale
-- "Solo con X" en vez de listar cada "Sin X"; si se quitan los 4, sale
-- "Solo carne".
--
-- De paso, se añade "Extra falafel +1,5€" al paso de extras de los 3
-- productos de falafel.
--
-- Reemplaza la columna modificadores entera por producto (más simple y
-- seguro de leer que ir parcheando con jsonb_set). Seguro de re-ejecutar.

update menu_productos set modificadores = '[{"id":"quitar","titulo":"Quitar ingredientes","tipo":"multiple","resumenQuitarMuchos":{"umbral":3,"siTodoVacio":"Solo carne"},"opciones":[{"id":"sin-tomate","nombre":"Sin tomate","ingrediente":"tomate","precioExtra":0,"porDefecto":false},{"id":"sin-cebolla","nombre":"Sin cebolla","ingrediente":"cebolla","precioExtra":0,"porDefecto":false},{"id":"sin-repollo-zanahoria","nombre":"Sin repollo y zanahoria","ingrediente":"repollo y zanahoria","precioExtra":0,"porDefecto":false},{"id":"sin-lechuga","nombre":"Sin lechuga","ingrediente":"lechuga","precioExtra":0,"porDefecto":false}],"precioSiTodoQuitado":5.5,"disparadoresPrecioAlternativo":["sin-lechuga","sin-repollo-zanahoria"]},{"id":"salsas","titulo":"Salsas","tipo":"multiple","textoSiVacio":"Sin salsa","opciones":[{"id":"salsa-blanca","nombre":"Salsa de yogurt (Blanca)","ingrediente":"salsa blanca","precioExtra":0,"porDefecto":true},{"id":"salsa-roja","nombre":"Salsa de tomate (Roja)","ingrediente":"salsa roja","precioExtra":0,"porDefecto":true},{"id":"salsa-picante","nombre":"Salsa picante","ingrediente":"salsa picante","precioExtra":0,"porDefecto":false}]},{"id":"extras","titulo":"Extras","tipo":"multiple","opciones":[{"id":"extra-salsa","nombre":"Extra salsa","precioExtra":1,"porDefecto":false},{"id":"extra-queso","nombre":"Extra queso","precioExtra":1,"porDefecto":false}]}]'::jsonb where id = 'kebab-ternera';
